#!/usr/bin/env python3
"""Make build_aar.py ship the classes generated by jni_zero.

Upstream WebRTC's AAR leaves out the *Jni classes (e.g. PeerConnectionFactoryJni)
and GEN_JNI, so apps crash with NoClassDefFoundError on the first WebRTC call.
Same fix as nextcloud-releases/talk-clients-webrtc PR #36.

Usage: patch_jni_zero_aar.py <webrtc src dir>
Fails loudly if the source does not look as expected, instead of guessing.
"""
import sys
from pathlib import Path

src = Path(sys.argv[1])

# 1. sdk/android/BUILD.gn: add the generated Java targets to dist_jar("libwebrtc").
gn = src / "sdk/android/BUILD.gn"
text = gn.read_text()
start = text.index('dist_jar("libwebrtc") {')
anchor = '      "../../third_party/jni_zero:jni_zero_java",\n    ]\n  }\n'
pos = text.index(anchor, start)
assert text.count('dist_jar("libwebrtc") {') == 1, "unexpected libwebrtc targets"
assert "libjingle_peerconnection_so_jni_registration_java" not in text, "already patched"

generated = [
    ":dav1d_java",
    ":generated_audio_device_module_base_jni_java",
    ":generated_base_jni_java",
    ":generated_builtin_audio_codecs_jni_java",
    ":generated_dav1d_jni_java",
    ":generated_environment_jni_java",
    ":generated_java_audio_device_module_native_jni_java",
    ":generated_java_audio_jni_java",
    ":generated_libaom_av1_encoder_jni_java",
    ":generated_libvpx_vp8_jni_java",
    ":generated_libvpx_vp9_jni_java",
    ":generated_logging_jni_java",
    ":generated_metrics_jni_java",
    ":generated_native_api_jni_java",
    ":generated_peerconnection_jni_java",
    ":generated_rtcerror_jni_java",
    ":generated_swcodecs_jni_java",
    ":generated_video_egl_jni_java",
    ":generated_video_jni_java",
    ":libjingle_peerconnection_so_jni_registration_java",
    "../../rtc_base:base_java_jni_java",
    "../../third_party/jni_zero:generate_jni_java",
]
for name in generated:
    if name.startswith(":generated_"):
        base = name[1:-len("_java")]
        assert f'generate_jni("{base}")' in text, f"missing target {base}"

replacement = (
    '      "../../third_party/jni_zero:jni_zero_java",\n'
    "\n      # Added by nabd-webrtc: classes generated by jni_zero.\n"
    + "".join(f'      "{n}",\n' for n in generated)
    + "    ]\n  }\n"
    + """
  # Added by nabd-webrtc: GEN_JNI for libjingle_peerconnection_so. It is normally
  # generated when an APK is built; an AAR has no APK, so we ship it here.
  java_library_impl("libjingle_peerconnection_so_jni_registration_java") {
    type = "java_library"
    supports_android = true
    requires_android = true
    srcjar_deps = [ ":libjingle_peerconnection_so__jni_registration" ]
    deps = [
      ":libjingle_peerconnection_metrics_default_java",
      "//third_party/jni_zero:jni_zero_java",
    ]
  }
"""
)
text = text[:pos] + replacement + text[pos + len(anchor):]
gn.write_text(text)
print(f"patched {gn}")

# 2. third_party/jni_zero/BUILD.gn: let sdk/android use generate_jni_java.
jz = src / "third_party/jni_zero/BUILD.gn"
jt = jz.read_text()
needle = '    "//components/cronet/android/*",\n'
assert jt.count(needle) == 1, "jni_zero visibility block changed"
jt = jt.replace(needle, needle + '    "//sdk/android:*",\n')
jz.write_text(jt)
print(f"patched {jz}")
